package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.io.*;import java.util.*;
public final class PcRoadMathReferenceExport {
 static DataOutputStream out;static ByteBuffer table;static NativeRoadAttributes attributes;static NativeRoadProjection projection;static int[] counts=new int[8];
 static void d(double[] values)throws Exception{for(double v:values)out.writeDouble(v);}static void ints(int... values)throws Exception{for(int v:values)out.writeInt(v);}static void raw(ByteBuffer b)throws Exception{byte[] v=new byte[b.remaining()];b.duplicate().get(v);out.write(v);}static void ring(double[][] r)throws Exception{out.writeInt(r.length);for(double[] v:r)d(v);}static void begin(int type)throws Exception{out.writeInt(type);counts[type]++;}
 static void vertex(double depth,int[] a,int shift,int height,int affine)throws Exception{double[] v=attributes.vertex(depth,a,shift,height,affine);begin(2);out.writeDouble(depth);ints(a);ints(shift,height,affine);d(v);}
 static void near(double a,double b,int[] uv,int shift,int height,int affine)throws Exception{double[] v=attributes.near(a,b,uv,shift,height,affine,64);begin(3);d(new double[]{a,b});ints(uv);ints(shift,height,affine,64);d(v);}
 static ByteBuffer camera(){ByteBuffer b=ByteBuffer.allocate(56).order(ByteOrder.LITTLE_ENDIAN);b.putInt(0,1);b.putInt(4,4);b.putInt(8,16384);b.putInt(8+8*4,16384);b.putInt(8+9*4,10);b.putInt(8+10*4,-5);b.putInt(8+11*4,20);return b;}
 static ByteBuffer source(int count,boolean affine){ByteBuffer b=ByteBuffer.allocate(288).order(ByteOrder.LITTLE_ENDIAN);b.putInt(0,count);b.putInt(4,7);b.putInt(8,64);b.putInt(12,affine?1:0);b.putInt(16,4);b.putInt(20,2);for(int i=0;i<count;i++){b.putInt(32+i*8,i*12345-17000);b.putInt(36+i*8,24000-i*7777);}return b;}
 public static void main(String[] args)throws Exception{Path output=Paths.get(args[1]);Files.createDirectories(output);int captured=0;try(DirectoryStream<Path> paths=Files.newDirectoryStream(Paths.get(args[0]),"source-race-background-*.nrb");DataOutputStream stream=new DataOutputStream(Files.newOutputStream(output.resolve("cases.bin")))){out=stream;
 for(Path path:paths){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(path)).sky.scene;for(int owner=0;owner<scene.geometryCount();owner++){NativeScenePacket packet=scene.geometry(owner);NativeWorldScene world=new NativeWorldScene(packet);if(table==null){table=world.reciprocal();attributes=new NativeRoadAttributes(table);projection=new NativeRoadProjection(table);byte[] data=new byte[table.remaining()];table.duplicate().get(data);Files.write(output.resolve("reciprocal.bin"),data);}else if(!table.equals(world.reciprocal()))throw new AssertionError("Different table");for(int i=0;i<world.surfaceCount();i++){NativeWorldScene.Surface surface=world.surface(i);if(surface.sourceAttributes()==null||surface.sourceCamera()!=null)continue;NativeWorldMesh mesh=new NativeWorldMesh(packet,world,i);DoubleBuffer camera=mesh.cameraVertices();double[][] points=new double[surface.corners][3];for(int v=0;v<points.length;v++)for(int k=0;k<3;k++)points[v][k]=camera.get();double[][] result=NativeRoadClip.clip(points,surface.sourceAttributes(),attributes);begin(4);out.writeInt(points.length);for(double[] v:points)d(v);raw(surface.sourceAttributes());ring(result);captured++;}}}
 ByteBuffer camera=camera();NativeRoadCamera roadCamera=new NativeRoadCamera(camera);for(double[] p:new double[][]{{0,0,0},{-.25,7.5,-.75},{32767.5,0,32767.5},{2147483646.,-5,-2147483648.},{-10.5,0,43.75}}){begin(1);raw(camera);d(p);d(roadCamera.point(p));}
 Random random=new Random(913);for(int i=0;i<300;i++){int shift=i%11,height=2*(1+i%64),affine=i%2;int[] uv={random.nextInt(),random.nextInt()};vertex(64+i%100+(i%3)*.25,uv,shift,height,affine);int[] pair={uv[0],uv[1],random.nextInt(),random.nextInt()};near(63-(i%5)*.25,64.25+i%100,pair,shift,height,affine);near(64.25+i%100,63-(i%5)*.25,pair,shift,height,affine);}
 int[] p={120,80,64};for(int i=0;i<180;i++){double[] point={i%11-5.25,i%7-3.5,64.25+i%100},uv={random.nextInt(200000)-100000+.25,random.nextInt(200000)-100000+.75};double[] result=projection.point(point,uv,i%11,2*(1+i%64),p);begin(5);d(point);d(uv);ints(i%11,2*(1+i%64));ints(p);d(result);}
 for(double[] depth:new double[][]{{63,65},{63.75,64.25},{63.999,64.001},{-100,64},{64,63},{64.5,-20.25}}){double[] a={-12.5,9.25,depth[0],17000.25,-34000.5},b={20.75,-10.5,depth[1],-23000.75,44000.25};double[] result=projection.near(a,b,64);begin(6);d(a);d(b);out.writeDouble(64);d(result);}
 for(boolean affine:new boolean[]{false,true})for(double depth:new double[]{43,43.75,44,44.25,80}){ByteBuffer attrs=source(4,affine);double[][] points={{-20,0,depth},{-20,0,80},{20,0,80},{20,0,depth}};double[][] result=projection.ring(points,attrs,roadCamera,p);begin(7);out.writeInt(points.length);for(double[] v:points)d(v);raw(attrs);raw(camera);ints(p);ring(result);}
 }Files.write(output.resolve("counts.txt"),(Arrays.toString(counts)+" captured="+captured).getBytes("UTF-8"));System.out.println("PASS_PC_ROAD_MATH_EXPORT "+Arrays.toString(counts)+" captured="+captured);}
}
